@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--cream:#e9e9d8;--muted:#a9b0a1;--lime:#c8dc86;--orange:#e09a67;--panel:rgba(13,22,18,.78);--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101a16;color:var(--cream);font-family:var(--sans);touch-action:none}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;height:100dvh;overflow:hidden;background:#17251d;isolation:isolate}#view{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 48%,transparent 34%,rgba(5,11,9,.16) 76%,rgba(5,9,8,.64) 130%);z-index:1}.topbar{position:absolute;z-index:2;top:max(18px,env(safe-area-inset-top));left:24px;right:24px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.brand{display:flex;gap:11px;align-items:center}.brand-mark{font-size:28px;color:var(--lime);font-weight:400}.brand b{font-size:12px;letter-spacing:2px;display:block;font-weight:800}.brand small{display:block;color:#aab2a4;font:9px var(--mono);letter-spacing:1.5px;margin-top:3px}.clock{position:absolute;left:50%;transform:translateX(-50%);text-align:center;min-width:120px;font:18px var(--mono);letter-spacing:2px}.clock small{font:8px var(--mono);color:#c1c6b8;letter-spacing:1.6px;display:block;margin-top:2px}.live-dot,.eyebrow span{display:inline-block;width:6px;height:6px;background:#d9a174;border-radius:50%;vertical-align:middle;margin-right:8px;box-shadow:0 0 12px #e49a62}.icon-btn{pointer-events:auto;background:rgba(10,18,14,.45);border:1px solid rgba(228,235,211,.25);border-radius:50%;height:38px;width:38px;font-size:15px;cursor:pointer;backdrop-filter:blur(8px)}.status-panel{position:absolute;z-index:2;top:93px;left:24px;width:164px;padding:13px 14px 11px;background:var(--panel);border:1px solid rgba(223,232,205,.15);backdrop-filter:blur(9px);border-radius:4px}.status-line{display:flex;justify-content:space-between;color:#c3cabb;font:9px var(--mono);letter-spacing:1.2px}.status-line span:last-child{color:#d5dfc4}.meter{height:3px;background:rgba(234,237,221,.18);margin-top:7px}.meter i{height:100%;display:block;width:100%;transition:width .3s}.health-fill{background:#b4cf8a}.hunger-line{margin-top:12px}.hunger-fill{background:#d7a66e}.thin{height:2px;margin-top:6px}.food-count{border-top:1px solid rgba(234,237,221,.12);padding-top:8px;margin-top:10px;display:flex;justify-content:space-between;color:#c3cabb;font:9px var(--mono);letter-spacing:1px}.food-count b{font-size:12px;color:var(--lime)}.objective{position:absolute;z-index:2;top:95px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;padding:8px 13px;background:rgba(10,18,14,.52);border:1px solid rgba(223,232,205,.13);color:#e2e4d7;font:10px var(--mono);letter-spacing:.35px;white-space:nowrap;backdrop-filter:blur(8px)}.objective-icon{font-size:16px;color:var(--lime)}.threat{position:absolute;z-index:3;top:154px;left:50%;transform:translate(-50%,-10px);display:flex;gap:10px;align-items:center;padding:9px 14px;border:1px solid rgba(205,89,61,.38);background:rgba(41,17,14,.7);opacity:0;transition:.3s;backdrop-filter:blur(6px)}.threat.active{opacity:1;transform:translate(-50%,0)}.threat-icon{color:#ed7154;font-size:17px}.threat b{display:block;color:#f09c7d;font:9px var(--mono);letter-spacing:1.1px}.threat small{display:block;color:#d4b8aa;font:9px var(--mono);margin-top:3px}.crosshair{position:absolute;z-index:2;left:50%;top:48%;width:18px;height:18px;transform:translate(-50%,-50%);pointer-events:none;opacity:.8}.crosshair i{position:absolute;background:rgba(239,242,222,.8)}.crosshair i:nth-child(1){width:1px;height:5px;left:8px;top:0}.crosshair i:nth-child(2){width:1px;height:5px;left:8px;bottom:0}.crosshair i:nth-child(3){width:5px;height:1px;left:0;top:8px}.crosshair i:nth-child(4){width:5px;height:1px;right:0;top:8px}.crosshair b{position:absolute;left:7px;top:7px;width:3px;height:3px;border:1px solid rgba(239,242,222,.8);border-radius:50%}.prompt{position:absolute;z-index:3;left:50%;top:55%;transform:translateX(-50%);padding:7px 10px;background:rgba(12,18,13,.75);color:#e3e7d6;font:9px var(--mono);letter-spacing:1px;opacity:0;transition:opacity .15s;white-space:nowrap}.prompt.show{opacity:1}.hit-flash{position:absolute;z-index:2;inset:0;pointer-events:none;border:0 solid rgba(216,64,43,0);transition:border .1s}.hit-flash.hit{border:10px solid rgba(216,64,43,.56)}.controls{position:absolute;z-index:4;bottom:max(28px,env(safe-area-inset-bottom));left:28px;right:28px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.move-pad{width:136px;display:flex;flex-direction:column;align-items:center;gap:7px;pointer-events:auto;user-select:none}.pad-ring{width:112px;height:112px;border-radius:50%;background:rgba(11,19,15,.36);border:1px solid rgba(225,234,212,.25);display:grid;place-items:center;backdrop-filter:blur(4px)}.stick{height:48px;width:48px;border-radius:50%;background:rgba(210,222,188,.34);border:1px solid rgba(235,240,217,.45);box-shadow:0 5px 18px #0c140f66;transform:translate(0,0)}.move-pad small{font:8px var(--mono);letter-spacing:1.6px;color:#d6dec9}.actions{display:flex;gap:10px;align-items:flex-end;pointer-events:auto}.action-btn{width:72px;height:72px;border-radius:50%;display:flex;flex-direction:column;justify-content:center;align-items:center;background:rgba(11,19,15,.55);border:1px solid rgba(225,234,212,.3);box-shadow:0 6px 20px #0003;backdrop-filter:blur(7px);cursor:pointer;user-select:none;transition:transform .12s,background .12s}.action-btn:active{transform:scale(.94);background:rgba(50,66,48,.82)}.action-btn span{font-size:22px;line-height:20px;color:var(--lime)}.action-btn b{font:9px var(--mono);letter-spacing:1.3px;margin-top:3px}.action-btn small{font:7px var(--mono);letter-spacing:.6px;color:#aab3a4;margin-top:2px}.fire{width:84px;height:84px;border-color:rgba(219,155,111,.5)}.fire span{color:#e5a678}.desktop-hint{position:absolute;z-index:2;bottom:18px;left:50%;transform:translateX(-50%);font:8px var(--mono);letter-spacing:1.1px;color:#e3e8d9aa;white-space:nowrap}.desktop-hint span{color:var(--lime);padding:0 5px}.screen{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:rgba(8,14,12,.62);backdrop-filter:blur(6px);opacity:0;visibility:hidden;transition:opacity .35s,visibility .35s;padding:24px}.screen.visible{opacity:1;visibility:visible}.modal-card{width:min(480px,100%);background:linear-gradient(145deg,rgba(26,39,30,.97),rgba(14,24,19,.98));border:1px solid rgba(205,220,183,.22);box-shadow:0 24px 100px #0008;padding:36px 40px;position:relative}.modal-card:before{content:'';position:absolute;top:-1px;left:32px;width:60px;height:2px;background:var(--lime)}.eyebrow{font:9px var(--mono);letter-spacing:1.8px;color:#c3ceb5;display:flex;align-items:center}.eyebrow span{width:5px;height:5px;background:var(--lime);box-shadow:0 0 10px var(--lime)}h1{font-size:clamp(34px,7vw,50px);line-height:.98;letter-spacing:-2px;margin:27px 0 17px;font-weight:700}h1 em{font-style:normal;color:var(--lime)}.modal-card p{color:#b8c0b3;font-size:13px;line-height:1.7;margin:0;max-width:390px}.briefing{display:flex;gap:28px;margin:25px 0 24px;padding-top:16px;border-top:1px solid #dfe6d01e}.briefing div{display:flex;flex-direction:column;gap:5px}.briefing small{color:#8e9b8a;font:8px var(--mono);letter-spacing:1.4px}.briefing b{font-size:11px;font-weight:600}.primary-btn{width:100%;height:48px;background:var(--lime);border:0;color:#1b281b;font:800 10px var(--mono);letter-spacing:1.25px;text-align:left;padding:0 16px;cursor:pointer;display:flex;align-items:center;justify-content:space-between}.primary-btn span{font-size:17px}.primary-btn:active{background:#e2edb5}.control-note{margin-top:13px;text-align:center;color:#8c998b;font:8px var(--mono);letter-spacing:.6px}.compact-card{width:min(360px,100%);text-align:center;padding:35px}.compact-card .eyebrow{justify-content:center}.compact-card h2{font-size:24px;margin:22px 0 5px}.compact-card p{margin:0 auto 24px}.reveal-card{width:min(510px,100%);padding:38px 42px}.reveal-card h1{font-size:58px}.reveal-card p{font-size:12px}.case-file{display:flex;flex-direction:column;gap:7px;background:#080e0c55;border-left:2px solid #cc735c;padding:12px 14px;margin:21px 0 22px;color:#bdc5b5;font:8px var(--mono);letter-spacing:.6px}.case-file b{color:#e6a188;font-size:10px}.toast{position:absolute;z-index:8;top:50%;left:50%;transform:translate(-50%,12px);padding:9px 14px;background:rgba(11,17,13,.82);border:1px solid #d8e1c32a;color:#e4e8d8;font:9px var(--mono);letter-spacing:.7px;opacity:0;pointer-events:none;transition:.2s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}
@media (min-width:800px){.status-panel{left:32px;top:104px;width:180px}.topbar{left:32px;right:32px}.controls{left:34px;right:34px;bottom:38px}.move-pad{opacity:.72}.actions{margin-right:3px}.action-btn{width:64px;height:64px}.fire{width:76px;height:76px}.desktop-hint{display:block}}
@media (max-width:600px){.topbar{left:15px;right:15px;top:max(13px,env(safe-area-inset-top))}.brand{gap:7px}.brand-mark{font-size:23px}.brand b{font-size:9px;letter-spacing:1.2px}.brand small{font-size:7px;letter-spacing:1px}.clock{font-size:15px;min-width:90px;left:54%}.clock small{font-size:7px}.icon-btn{width:34px;height:34px}.status-panel{left:13px;top:72px;width:140px;padding:10px 11px 9px}.objective{top:73px;left:auto;right:13px;transform:none;font-size:8px;padding:7px 9px;max-width:calc(100% - 170px);overflow:hidden}.threat{top:122px;max-width:92%;white-space:nowrap}.crosshair{top:47%}.controls{left:12px;right:12px;bottom:max(17px,env(safe-area-inset-bottom));align-items:flex-end}.move-pad{width:112px}.pad-ring{width:96px;height:96px}.stick{width:42px;height:42px}.actions{gap:8px}.action-btn{width:62px;height:62px}.fire{width:72px;height:72px}.desktop-hint{display:none}.modal-card{padding:30px 25px}.briefing{gap:17px}.reveal-card h1{font-size:48px}.screen{padding:17px}}
@media (max-height:520px) and (orientation:landscape){.status-panel{top:68px}.objective{top:68px}.controls{bottom:8px}.move-pad{width:88px}.pad-ring{width:76px;height:76px}.stick{width:38px;height:38px}.move-pad small{display:none}.action-btn{width:56px;height:56px}.fire{width:66px;height:66px}.modal-card{padding:22px 30px}.modal-card h1{font-size:37px;margin:15px 0 10px}.briefing{margin:15px 0}.control-note{margin-top:8px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas = document.querySelector('#view');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9ba78c);
scene.fog = new THREE.FogExp2(0x9ba78c, 0.018);
const camera = new THREE.PerspectiveCamera(72, innerWidth / innerHeight, 0.1, 180);
camera.position.set(0, 1.68, 0);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
scene.add(new THREE.HemisphereLight(0xdce5cb, 0x354332, 1.5));
const sun = new THREE.DirectionalLight(0xffdfad, 2.4);
sun.position.set(-32, 48, -18); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -55; sun.shadow.camera.right = 55;
sun.shadow.camera.top = 55; sun.shadow.camera.bottom = -55; sun.shadow.bias = -0.0007;
scene.add(sun);

const mat = (color, roughness = 1) => new THREE.MeshStandardMaterial({ color, roughness, flatShading: true });
const groundMat = mat(0x526448), barkMat = mat(0x49382a), leafMats = [mat(0x304b36), mat(0x3c5a3c), mat(0x49643d), mat(0x566e42)];
const ground = new THREE.Mesh(new THREE.PlaneGeometry(260, 260), groundMat);
ground.rotation.x = -Math.PI / 2; ground.position.y = -0.12; ground.receiveShadow = true; scene.add(ground);
// A pale, winding deer trail gives the forest a readable path.
const pathPoints = [];
for (let i = 0; i <= 28; i++) { const z = 65 - i * 4.65; pathPoints.push(new THREE.Vector3(Math.sin(i * .22) * 5, -.105, z)); }
const pathCurve = new THREE.CatmullRomCurve3(pathPoints);
const pathMesh = new THREE.Mesh(new THREE.TubeGeometry(pathCurve, 120, 2.25, 7, false), mat(0x827a5d));
pathMesh.rotation.x = Math.PI / 2; pathMesh.position.y = -.095; pathMesh.scale.y = .32; scene.add(pathMesh);

const treeSpots = [];
function makeTree(x, z, scale = 1) {
  const group = new THREE.Group(); group.position.set(x, 0, z); group.scale.setScalar(scale);
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(.24, .38, 4.2, 6), barkMat); trunk.position.y = 2.05; trunk.castShadow = true; group.add(trunk);
  const leaf = leafMats[Math.floor(Math.random() * leafMats.length)];
  for (let i = 0; i < 3; i++) {
    const crown = new THREE.Mesh(new THREE.ConeGeometry(2.35 - i * .24, 4.7 - i * .3, 7), leaf);
    crown.position.set((Math.random() - .5) * .28, 4.4 + i * 1.38, (Math.random() - .5) * .25);
    crown.rotation.y = Math.random() * 1.5; crown.castShadow = true; group.add(crown);
  }
  scene.add(group); treeSpots.push({ x, z, r: 1.05 * scale });
}
for (let z = -88; z <= 82; z += 8) {
  for (let x = -88; x <= 88; x += 8) {
    const d = Math.hypot(x, z);
    if (d < 8 || Math.random() > .82) continue;
    const px = x + (Math.random() - .5) * 6, pz = z + (Math.random() - .5) * 6;
    const pathX = Math.sin((65 - pz) / 4.65 * .22) * 5;
    if (Math.abs(px - pathX) < 4.8 && Math.random() < .9) continue;
    makeTree(px, pz, .72 + Math.random() * .75);
  }
}
// Fallen logs, stones and ferns add cover and silhouettes without heavy assets.
const rockMat = mat(0x656957), fernMat = mat(0x71834d);
for (let i = 0; i < 54; i++) {
  const x = (Math.random() - .5) * 150, z = (Math.random() - .5) * 150;
  if (Math.hypot(x, z) < 7) continue;
  if (Math.random() < .45) {
    const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(.35 + Math.random() * .45, 0), rockMat);
    rock.position.set(x, .12, z); rock.scale.y = .62; rock.rotation.set(Math.random(), Math.random(), Math.random()); rock.castShadow = true; rock.receiveShadow = true; scene.add(rock);
  } else {
    const bush = new THREE.Group(); bush.position.set(x, 0, z);
    for (let j = 0; j < 5; j++) { const frond = new THREE.Mesh(new THREE.ConeGeometry(.12, .8 + Math.random() * .35, 4), fernMat); frond.position.set((Math.random() - .5) * .65, .35, (Math.random() - .5) * .65); frond.rotation.z = (Math.random() - .5) * .9; bush.add(frond); }
    scene.add(bush);
  }
}

// First-person field rifle, attached to the camera so the player always has a clear action cue.
const rifle = new THREE.Group();
const gunMetal = new THREE.MeshStandardMaterial({ color: 0x202723, metalness: .48, roughness: .48 });
const wood = mat(0x654b32), cloth = mat(0x303b31);
function gunPart(geometry, material, pos, rot = [0, 0, 0]) { const m = new THREE.Mesh(geometry, material); m.position.set(...pos); m.rotation.set(...rot); rifle.add(m); return m; }
gunPart(new THREE.BoxGeometry(.13, .14, .72), wood, [-.04, -.04, -.12], [0, -.12, -.18]);
gunPart(new THREE.BoxGeometry(.12, .13, .42), gunMetal, [-.015, .015, -.48]);
gunPart(new THREE.CylinderGeometry(.027, .027, .86, 8), gunMetal, [.015, .07, -.91], [Math.PI / 2, 0, 0]);
gunPart(new THREE.CylinderGeometry(.055, .055, .24, 8), gunMetal, [.015, .085, -.67], [Math.PI / 2, 0, 0]);
gunPart(new THREE.BoxGeometry(.08, .27, .12), cloth, [-.02, -.22, -.45], [-.2, 0, -.08]);
gunPart(new THREE.BoxGeometry(.11, .13, .18), wood, [-.05, -.13, .18], [.18, 0, -.15]);
camera.add(rifle); rifle.position.set(.35, -.38, -.48); scene.add(camera);

const animals = [];
const animalMats = { body: mat(0x956e4e), light: mat(0xc3a17a), dark: mat(0x493e32), eye: new THREE.MeshStandardMaterial({ color: 0x171710, roughness: .4 }), fur: mat(0x9b8a69) };
function makeAnimal(x, z, kind = 'deer') {
  const isDeer = kind === 'deer', root = new THREE.Group(); root.position.set(x, 0, z); root.userData.kind = kind;
  const body = new THREE.Mesh(new THREE.SphereGeometry(1, 8, 6), isDeer ? animalMats.body : animalMats.fur);
  body.scale.set(isDeer ? .88 : .43, isDeer ? .5 : .4, isDeer ? .43 : .62); body.position.y = isDeer ? 1.15 : .5; body.castShadow = true; root.add(body);
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(isDeer ? .19 : .08, isDeer ? .3 : .14, isDeer ? .78 : .24, 6), isDeer ? animalMats.light : animalMats.fur);
  neck.position.set(0, isDeer ? 1.42 : .67, isDeer ? -.48 : -.39); neck.rotation.x = -.35; root.add(neck);
  const head = new THREE.Mesh(new THREE.SphereGeometry(isDeer ? .28 : .18, 7, 5), isDeer ? animalMats.light : animalMats.fur);
  head.position.set(0, isDeer ? 1.78 : .74, isDeer ? -.75 : -.74); root.add(head);
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(.045, 5, 4), animalMats.eye); eye.position.set(side * .22, isDeer ? 1.81 : .76, isDeer ? -.83 : -.86); root.add(eye);
    if (isDeer) {
      const ear = new THREE.Mesh(new THREE.ConeGeometry(.09, .3, 4), animalMats.body); ear.position.set(side * .22, 1.99, -.68); ear.rotation.z = side * -.45; root.add(ear);
      const antler = new THREE.Group(); antler.position.set(side * .1, 2.02, -.72); antler.rotation.z = side * .24;
      const stem = new THREE.Mesh(new THREE.CylinderGeometry(.027, .05, .58, 5), animalMats.dark); stem.position.y = .27; antler.add(stem);
      for (let k = 0; k < 2; k++) { const tine = new THREE.Mesh(new THREE.CylinderGeometry(.016, .03, .29, 4), animalMats.dark); tine.position.set(side * (k ? -.13 : .13), .38 + k * .12, 0); tine.rotation.z = side * (k ? -.55 : .65); antler.add(tine); }
      root.add(antler);
    }
  }
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const leg = new THREE.Mesh(new THREE.CylinderGeometry(isDeer ? .055 : .045, .045, isDeer ? .72 : .34, 5), animalMats.dark);
    leg.position.set(sx * (isDeer ? .49 : .24), isDeer ? .52 : .25, sz * (isDeer ? .25 : .37)); leg.rotation.x = sz * -.12; leg.castShadow = true; root.add(leg);
  }
  scene.add(root);
  animals.push({ root, kind, alive: true, speed: .32 + Math.random() * .25, phase: Math.random() * 8, flee: 0 });
}
makeAnimal(8, -16, 'deer'); makeAnimal(-13, -27, 'deer'); makeAnimal(15, -42, 'deer');
makeAnimal(-7, 11, 'rabbit'); makeAnimal(19, -11, 'rabbit'); makeAnimal(-22, 6, 'rabbit');

input.newString:
makeAnimal(-7, 11, 'rabbit'); makeAnimal(19, -11, 'rabbit'); makeAnimal(-22, 6, 'rabbit');

// The pursuer is a distant, hooded silhouette: visible enough to read, never a gore prop.
const hunter = new THREE.Group();
const hunterMat = mat(0x171c19), coatMat = mat(0x343b32), maskMat = mat(0xb9a98b), scopeMat = new THREE.MeshStandardMaterial({ color: 0x8a3026, emissive: 0x6d160e, emissiveIntensity: 1.1 });
function hunterPart(g, material, pos, scale) { const m = new THREE.Mesh(g, material); m.position.set(...pos); if (scale) m.scale.set(...scale); m.castShadow = true; hunter.add(m); return m; }
hunterPart(new THREE.CylinderGeometry(.25, .48, 1.55, 6), coatMat, [0, .95, 0]);
hunterPart(new THREE.SphereGeometry(.31, 7, 6), hunterMat, [0, 1.94, -.03], [1, 1.15, .95]);
hunterPart(new THREE.BoxGeometry(.37, .16, .15), maskMat, [0, 1.84, -.27]);
hunterPart(new THREE.BoxGeometry(.06, .06, .04), scopeMat, [0, 1.88, -.36]);
hunterPart(new THREE.CylinderGeometry(.035, .045, 1.35, 6), gunMetal, [.37, 1.62, -.4], [Math.PI / 2, 0, -.12]);
for (const s of [-1, 1]) hunterPart(new THREE.CylinderGeometry(.1, .12, .85, 5), hunterMat, [s * .28, .36, 0]);
hunter.position.set(14, 0, -26); hunter.visible = false; scene.add(hunter);
const laserGeometry = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
const laser = new THREE.Line(laserGeometry, new THREE.LineBasicMaterial({ color: 0xe94e36, transparent: true, opacity: .8 })); laser.visible = false; scene.add(laser);

const raycaster = new THREE.Raycaster(); raycaster.far = 64;
const ui = {
  clock: document.querySelector('#clock'), health: document.querySelector('#health-fill'), hunger: document.querySelector('#hunger-fill'),
  hungerLabel: document.querySelector('#hunger-label'), condition: document.querySelector('#condition'), food: document.querySelector('#food-count'),
  objective: document.querySelector('#objective-text'), prompt: document.querySelector('#prompt'), threat: document.querySelector('#threat'),
  flash: document.querySelector('#hit-flash'), toast: document.querySelector('#toast'), stick: document.querySelector('#stick')
};
let started = false, paused = false, ended = false, elapsed = 0, health = 100, hunger = 100, rations = 0;
