276: function updatePlayer(dt) {
277:   const forward = (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0) - move.y;
278:   const sideways = (keys.has('d') || keys.has('arrowright') ? 1 : 0) - (keys.has('a') || keys.has('arrowleft') ? 1 : 0) + move.x;
279:   const mag = Math.hypot(forward, sideways), sprint = keys.has('shift');
280:   const speed = 5.1 * (sprint ? 1.45 : 1);
281:   if (mag > .03) {
282:     const f = forward / Math.max(1, mag), s = sideways / Math.max(1, mag);
283:     const dx = (Math.sin(yaw) * f + Math.cos(yaw) * s) * speed * dt;
284:     const dz = (-Math.cos(yaw) * f + Math.sin(yaw) * s) * speed * dt;
285:     const nx = camera.position.x + dx, nz = camera.position.z + dz;
286:     const blocked = treeSpots.some(t => Math.hypot(nx - t.x, nz - t.z) < t.r + .45);
287:     if (!blocked) { camera.position.x = nx; camera.position.z = nz; }
288:     camera.position.x = clamp(camera.position.x, -100, 100); camera.position.z = clamp(camera.position.z, -100, 100);
289:     rifle.position.y = -.38 + Math.sin(elapsed * (sprint ? 14 : 9)) * .012 * Math.min(mag, 1);
290:   }
291:   camera.rotation.order = 'YXZ'; camera.rotation.set(pitch, yaw, 0);
292: }
293: function updateAnimals(dt) {
294:   for (const a of animals) {
295:     if (!a.alive) continue;
296:     a.phase += dt * (a.kind === 'deer' ? 2 : 3.5);
297:     const dx = a.root.position.x - camera.position.x, dz = a.root.position.z - camera.position.z, d = Math.hypot(dx, dz);
298:     if (d < (a.kind === 'deer' ? 10 : 7)) a.flee = Math.max(a.flee, 2.8);
299:     if (a.flee > 0) {
300:       a.flee -= dt; a.root.position.x += (dx / Math.max(d, .1)) * dt * a.speed * 8;
301:       a.root.position.z += (dz / Math.max(d, .1)) * dt * a.speed * 8;
302:       a.root.rotation.y = Math.atan2(-dx, dz);
303:     } else {
304:       a.root.position.x += Math.sin(a.phase * .36) * dt * a.speed * .28;
305:       a.root.position.z += Math.cos(a.phase * .31) * dt * a.speed * .22;
306:       a.root.rotation.y = Math.sin(a.phase * .36) * .55;
307:     }
308:     const bounce = Math.sin(a.phase * (a.flee > 0 ? 9 : 2)) * (a.flee > 0 ? .08 : .018);
309:     a.root.children[0].position.y = (a.kind === 'deer' ? 1.15 : .5) + bounce;
310:   }
